import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const root = path.resolve(__dirname, '..');

const cronCode = fs.readFileSync(path.join(root, 'tgcloud/endpoints/cron.js'), 'utf8');
const remindersCode = fs.readFileSync(path.join(root, 'tgcloud/lib/reminders.js'), 'utf8');
const schemaCode = fs.readFileSync(path.join(root, 'tgcloud/schema.js'), 'utf8');

const content = `// Auto-generated by bundle-sources.js - DO NOT EDIT MANUALLY
export const cronSources = {
  'endpoints/cron': ${JSON.stringify(cronCode)},
  'lib/reminders': ${JSON.stringify(remindersCode)},
  'schema': ${JSON.stringify(schemaCode)},
};
`;

fs.mkdirSync(path.join(__dirname, 'src'), { recursive: true });
fs.writeFileSync(path.join(__dirname, 'src/sources.js'), content, 'utf8');
console.log('✓ Successfully bundled tgcloud sources for Cloudflare Worker');
